-- Generated by scripts/generate-baladiyah-final-assessment.ts.
-- Restructures only the exact normalized Baladiyah draft into one course-level final assessment.

create or replace function private.baladiyah_final_assessment_slots_match(
  target_organization_id uuid,
  target_course_version_id uuid,
  expected_slots jsonb
)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'module_key', slot.module_key,
        'lesson_key', slot.lesson_key,
        'asset_key', slot.asset_key,
        'placement', slot.placement,
        'slot_position', slot.slot_position
      ) order by slot.module_position, slot.lesson_position, slot.slot_position
    ),
    '[]'::jsonb
  ) = expected_slots
  from private.training_image_slot_requirements(target_organization_id, target_course_version_id) slot;
$$;

create or replace function private.baladiyah_final_assessment_source_matches(
  target_organization_id uuid,
  target_course_id uuid,
  target_course_version_id uuid,
  expected_target_manifest jsonb,
  expected_source_quizzes jsonb,
  expected_slots jsonb
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  drifted_instructional_lessons text;
begin
  if not exists (
    select 1
    from public.training_courses course
    join public.training_course_versions version
      on version.course_id = course.id
     and version.organization_id = course.organization_id
    where course.id = target_course_id
      and course.organization_id = target_organization_id
      and course.course_key = 'baladiyah-food-safety-hygiene'
      and course.status = 'active'
      and course.archived_at is null
      and version.id = target_course_version_id
      and version.version_number = 1
      and version.status = 'draft'
      and version.revision = 1
      and version.content_hash = '5d77e1c5d9c127a7a07fb0caf0703b52a0df2b16e0510632ff57bf4c09cf1515'
      and version.default_locale = expected_target_manifest #>> '{course,default_locale}'
      and version.supported_locales = array(
        select jsonb_array_elements_text(expected_target_manifest #> '{course,supported_locales}')
      )
      and version.title_i18n = expected_target_manifest #> '{course,title_i18n}'
      and version.description_i18n = expected_target_manifest #> '{course,description_i18n}'
      and version.content_schema_version = (expected_target_manifest ->> 'manifest_schema_version')::integer
      and version.published_at is null
      and version.published_by is null
      and version.retired_at is null
      and version.retired_by is null
  ) then
    raise exception 'Baladiyah final assessment version precondition drifted' using errcode = '55000';
  end if;

  if (select count(*) from public.training_modules where course_version_id = target_course_version_id) <> 9
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id) <> 27
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'reading') <> 9
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'key_points') <> 9
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'quiz') <> 9 then
    raise exception 'Baladiyah final assessment count precondition drifted' using errcode = '55000';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(expected_target_manifest -> 'modules') expected(module_value)
    where (expected.module_value ->> 'position')::integer <= 9
      and not exists (
        select 1
        from public.training_modules module
        where module.organization_id = target_organization_id
          and module.course_version_id = target_course_version_id
          and module.stable_key = expected.module_value ->> 'stable_key'
          and module.position = (expected.module_value ->> 'position')::integer
          and module.category_key is not distinct from expected.module_value ->> 'category_key'
          and module.title_i18n = expected.module_value -> 'title_i18n'
          and module.description_i18n = expected.module_value -> 'description_i18n'
          and module.metadata = expected.module_value -> 'metadata'
      )
  ) then
    raise exception 'Baladiyah final assessment module precondition drifted' using errcode = '55000';
  end if;

  select string_agg(
    (expected_module.module_value ->> 'stable_key') || ':' || (expected_lesson.lesson_value ->> 'stable_key'),
    ',' order by (expected_module.module_value ->> 'position')::integer,
      (expected_lesson.lesson_value ->> 'position')::integer
  )
  into drifted_instructional_lessons
    from jsonb_array_elements(expected_target_manifest -> 'modules') expected_module(module_value)
    cross join lateral jsonb_array_elements(expected_module.module_value -> 'lessons') expected_lesson(lesson_value)
    where (expected_module.module_value ->> 'position')::integer <= 9
      and not exists (
        select 1
        from public.training_modules module
        join public.training_lessons lesson
          on lesson.module_id = module.id
         and lesson.course_version_id = module.course_version_id
         and lesson.organization_id = module.organization_id
        where module.organization_id = target_organization_id
          and module.course_version_id = target_course_version_id
          and module.stable_key = expected_module.module_value ->> 'stable_key'
          and lesson.stable_key = expected_lesson.lesson_value ->> 'stable_key'
          and lesson.position = (expected_lesson.lesson_value ->> 'position')::integer
          and lesson.lesson_type = expected_lesson.lesson_value ->> 'lesson_type'
          and lesson.required = (expected_lesson.lesson_value ->> 'required')::boolean
          and lesson.title_i18n = expected_lesson.lesson_value -> 'title_i18n'
          and lesson.objective_i18n = expected_lesson.lesson_value -> 'objective_i18n'
          and lesson.content_i18n = expected_lesson.lesson_value -> 'content_i18n'
          and lesson.estimated_duration_seconds is not distinct from (expected_lesson.lesson_value ->> 'estimated_duration_seconds')::integer
          and lesson.minimum_engagement_seconds = (expected_lesson.lesson_value ->> 'minimum_engagement_seconds')::integer
          and lesson.pass_threshold_bps is not distinct from (expected_lesson.lesson_value ->> 'pass_threshold_bps')::integer
          and lesson.max_attempts is not distinct from (expected_lesson.lesson_value ->> 'max_attempts')::integer
          and lesson.retry_delay_seconds = (expected_lesson.lesson_value ->> 'retry_delay_seconds')::integer
          and lesson.metadata = expected_lesson.lesson_value -> 'metadata'
      );
  if drifted_instructional_lessons is not null then
    raise exception 'Baladiyah final assessment instructional lesson precondition drifted: %', drifted_instructional_lessons
      using errcode = '55000';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(expected_source_quizzes) expected(source_value)
    where not exists (
      select 1
      from public.training_modules module
      join public.training_lessons lesson
        on lesson.module_id = module.id
       and lesson.course_version_id = module.course_version_id
       and lesson.organization_id = module.organization_id
      where module.organization_id = target_organization_id
        and module.course_version_id = target_course_version_id
        and module.stable_key = expected.source_value ->> 'source_module_key'
        and module.position = (expected.source_value ->> 'source_module_position')::integer
        and lesson.stable_key = expected.source_value #>> '{lesson,stable_key}'
        and lesson.position = (expected.source_value #>> '{lesson,position}')::integer
        and lesson.lesson_type = 'quiz'
        and lesson.required = (expected.source_value #>> '{lesson,required}')::boolean
        and lesson.title_i18n = expected.source_value #> '{lesson,title_i18n}'
        and lesson.objective_i18n = expected.source_value #> '{lesson,objective_i18n}'
        and lesson.content_i18n = expected.source_value #> '{lesson,content_i18n}'
        and lesson.estimated_duration_seconds is not distinct from (expected.source_value #>> '{lesson,estimated_duration_seconds}')::integer
        and lesson.minimum_engagement_seconds = (expected.source_value #>> '{lesson,minimum_engagement_seconds}')::integer
        and lesson.pass_threshold_bps = 8000
        and lesson.max_attempts is null
        and lesson.retry_delay_seconds = 0
        and lesson.metadata = expected.source_value #> '{lesson,metadata}'
    )
  ) then
    raise exception 'Baladiyah final assessment quiz payload precondition drifted' using errcode = '55000';
  end if;

  if (
    select count(*)
    from public.training_lessons lesson
    cross join lateral jsonb_array_elements(lesson.content_i18n -> 'en' -> 'questions') question(value)
    where lesson.course_version_id = target_course_version_id
      and lesson.lesson_type = 'quiz'
  ) <> 27
  or (
    select count(distinct question.value ->> 'stable_key')
    from public.training_lessons lesson
    cross join lateral jsonb_array_elements(lesson.content_i18n -> 'en' -> 'questions') question(value)
    where lesson.course_version_id = target_course_version_id
      and lesson.lesson_type = 'quiz'
  ) <> 27
  or exists (
    select 1
    from public.training_lessons lesson
    where lesson.course_version_id = target_course_version_id
      and lesson.lesson_type = 'quiz'
      and jsonb_path_exists(lesson.content_i18n, '$.**.correct_option_key')
  ) then
    raise exception 'Baladiyah final assessment question precondition drifted' using errcode = '55000';
  end if;

  if not private.training_image_slot_bindings_valid(target_organization_id, target_course_version_id)
    or not private.baladiyah_final_assessment_slots_match(
      target_organization_id,
      target_course_version_id,
      expected_slots
    ) then
    raise exception 'Baladiyah final assessment image-slot precondition drifted' using errcode = '55000';
  end if;

  return true;
end;
$$;

create or replace function private.baladiyah_final_assessment_target_matches(
  target_organization_id uuid,
  target_course_id uuid,
  target_course_version_id uuid,
  expected_target_manifest jsonb,
  expected_target_hash text,
  expected_slots jsonb
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  final_quiz_metadata jsonb;
begin
  if not exists (
    select 1
    from public.training_courses course
    join public.training_course_versions version
      on version.course_id = course.id
     and version.organization_id = course.organization_id
    where course.id = target_course_id
      and course.organization_id = target_organization_id
      and course.course_key = 'baladiyah-food-safety-hygiene'
      and course.status = 'active'
      and course.archived_at is null
      and version.id = target_course_version_id
      and version.version_number = 1
      and version.status = 'draft'
      and version.revision = 2
      and version.content_hash = expected_target_hash
      and version.default_locale = expected_target_manifest #>> '{course,default_locale}'
      and version.supported_locales = array(
        select jsonb_array_elements_text(expected_target_manifest #> '{course,supported_locales}')
      )
      and version.title_i18n = expected_target_manifest #> '{course,title_i18n}'
      and version.description_i18n = expected_target_manifest #> '{course,description_i18n}'
      and version.content_schema_version = (expected_target_manifest ->> 'manifest_schema_version')::integer
      and version.published_at is null
      and version.published_by is null
      and version.retired_at is null
      and version.retired_by is null
  ) then
    return false;
  end if;

  if (select count(*) from public.training_modules where course_version_id = target_course_version_id) <> 10
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id) <> 19
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'reading') <> 9
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'key_points') <> 9
    or (select count(*) from public.training_lessons where course_version_id = target_course_version_id and lesson_type = 'quiz') <> 1 then
    return false;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(expected_target_manifest -> 'modules') expected(module_value)
    where not exists (
      select 1
      from public.training_modules module
      where module.organization_id = target_organization_id
        and module.course_version_id = target_course_version_id
        and module.stable_key = expected.module_value ->> 'stable_key'
        and module.position = (expected.module_value ->> 'position')::integer
        and module.category_key is not distinct from expected.module_value ->> 'category_key'
        and module.title_i18n = expected.module_value -> 'title_i18n'
        and module.description_i18n = expected.module_value -> 'description_i18n'
        and module.metadata = expected.module_value -> 'metadata'
    )
  ) then
    return false;
  end if;

  if exists (
    select 1
    from jsonb_array_elements(expected_target_manifest -> 'modules') expected_module(module_value)
    cross join lateral jsonb_array_elements(expected_module.module_value -> 'lessons') expected_lesson(lesson_value)
    where not exists (
      select 1
      from public.training_modules module
      join public.training_lessons lesson
        on lesson.module_id = module.id
       and lesson.course_version_id = module.course_version_id
       and lesson.organization_id = module.organization_id
      where module.organization_id = target_organization_id
        and module.course_version_id = target_course_version_id
        and module.stable_key = expected_module.module_value ->> 'stable_key'
        and lesson.stable_key = expected_lesson.lesson_value ->> 'stable_key'
        and lesson.position = (expected_lesson.lesson_value ->> 'position')::integer
        and lesson.lesson_type = expected_lesson.lesson_value ->> 'lesson_type'
        and lesson.required = (expected_lesson.lesson_value ->> 'required')::boolean
        and lesson.title_i18n = expected_lesson.lesson_value -> 'title_i18n'
        and lesson.objective_i18n = expected_lesson.lesson_value -> 'objective_i18n'
        and lesson.content_i18n = expected_lesson.lesson_value -> 'content_i18n'
        and lesson.estimated_duration_seconds is not distinct from (expected_lesson.lesson_value ->> 'estimated_duration_seconds')::integer
        and lesson.minimum_engagement_seconds = (expected_lesson.lesson_value ->> 'minimum_engagement_seconds')::integer
        and lesson.pass_threshold_bps is not distinct from (expected_lesson.lesson_value ->> 'pass_threshold_bps')::integer
        and lesson.max_attempts is not distinct from (expected_lesson.lesson_value ->> 'max_attempts')::integer
        and lesson.retry_delay_seconds = (expected_lesson.lesson_value ->> 'retry_delay_seconds')::integer
        and lesson.metadata = expected_lesson.lesson_value -> 'metadata'
    )
  ) then
    return false;
  end if;

  select lesson.metadata
  into final_quiz_metadata
  from public.training_modules module
  join public.training_lessons lesson
    on lesson.module_id = module.id
   and lesson.course_version_id = module.course_version_id
   and lesson.organization_id = module.organization_id
  where module.organization_id = target_organization_id
    and module.course_version_id = target_course_version_id
    and module.stable_key = 'final-assessment'
    and lesson.stable_key = 'final-quiz';

  if final_quiz_metadata ->> 'assessment_scope' <> 'course'
    or jsonb_array_length(final_quiz_metadata -> 'question_groups') <> 9
    or exists (
      select 1
      from jsonb_array_elements(final_quiz_metadata -> 'question_groups') grouping(value)
      where jsonb_array_length(grouping.value -> 'question_keys') <> 3
    )
    or (
      select count(*)
      from public.training_lessons lesson
      cross join lateral jsonb_array_elements(lesson.content_i18n -> 'en' -> 'questions') question(value)
      where lesson.course_version_id = target_course_version_id
        and lesson.lesson_type = 'quiz'
    ) <> 27
    or (
      select count(distinct question.value ->> 'stable_key')
      from public.training_lessons lesson
      cross join lateral jsonb_array_elements(lesson.content_i18n -> 'en' -> 'questions') question(value)
      where lesson.course_version_id = target_course_version_id
        and lesson.lesson_type = 'quiz'
    ) <> 27
    or jsonb_path_exists(
      (select lesson.content_i18n from public.training_lessons lesson where lesson.course_version_id = target_course_version_id and lesson.lesson_type = 'quiz'),
      '$.**.correct_option_key'
    ) then
    return false;
  end if;

  return private.training_image_slot_bindings_valid(target_organization_id, target_course_version_id)
    and private.baladiyah_final_assessment_slots_match(
      target_organization_id,
      target_course_version_id,
      expected_slots
    );
exception
  when others then
    return false;
end;
$$;

create or replace function private.restructure_baladiyah_final_assessment()
returns void
language plpgsql
security definer
set search_path = ''
as $function$
declare
  expected_target_manifest constant jsonb := $manifest$
{
  "manifest_schema_version": 1,
  "curriculum_status": "draft",
  "translation_review_status": "draft",
  "regulatory_status": "unverified_supporting_content",
  "course": {
