                },
                {
                  "fact_key": "clean-uniform-grooming",
                  "presentation": "key_point",
                  "position": 2,
                  "text": "Wear a clean work uniform from the restaurant locker, cover hair, use a beard net, keep nails short and unpolished, and remove operational jewelry.",
                  "provenance_classification": "baladiyah_explicit"
                }
              ],
