          "objective_i18n": {
            "en": "Follow the source-supported handwashing sequence and identify correct wound protection.",
            "ar": "اتباع تسلسل غسل اليدين المدعوم بالمصدر والتعرّف على الحماية الصحيحة للجروح.",
            "id": "Mengikuti urutan cuci tangan yang didukung sumber dan mengenali perlindungan luka yang benar.",
            "hi": "स्रोत-समर्थित हाथ धोने का क्रम अपनाएँ और घाव की सही सुरक्षा पहचानें।",
            "fil": "Sundin ang source-supported na paghuhugas ng kamay at tukuyin ang tamang proteksiyon sa sugat."
          },
          "content_i18n": {
            "en": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "procedure",
              "items": [
                {
                  "fact_key": "handwash-wet",
                  "presentation": "step",
                  "position": 1,
                  "text": "Wet hands with warm running water at 38°C-43°C.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-soap",
                  "presentation": "step",
                  "position": 2,
                  "text": "Use antibacterial liquid soap, not bar soap.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-scrub",
                  "presentation": "step",
                  "position": 3,
                  "text": "Scrub palms, backs of hands, between fingers, under nails, thumbs, and wrists for at least 20 seconds.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-dry",
                  "presentation": "step",
                  "position": 4,
                  "text": "Dry with a single-use paper towel or air dryer, then use the towel to turn off the tap.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-triggers",
                  "presentation": "key_point",
                  "position": 5,
                  "text": "Wash hands before a shift and after using the toilet, touching the face or hair, coughing or sneezing, handling raw food or waste, or touching cash or cashier devices.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "protected-cut",
                  "presentation": "warning",
                  "position": 6,
                  "text": "Treat cuts with antiseptic, cover them with a blue waterproof bandage, and protect them with disposable gloves.",
                  "provenance_classification": "baladiyah_explicit"
                }
              ],
              "image_slots": [
                {
