              "items": [
                {
                  "fact_key": "handwash-wet",
                  "presentation": "step",
                  "position": 1,
                  "text": "بلّل اليدين بماء جارٍ دافئ بدرجة 38°C-43°C.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-soap",
                  "presentation": "step",
                  "position": 2,
                  "text": "استخدم صابوناً سائلاً مضاداً للبكتيريا، وليس صابوناً صلباً.",
                  "provenance_classification": "baladiyah_explicit"
