                {
                  "fact_key": "handwash-scrub",
                  "presentation": "step",
                  "position": 3,
                  "text": "افرك راحتي اليدين وظهرهما وبين الأصابع وتحت الأظافر والإبهامين والمعصمين لمدة لا تقل عن 20 ثانية.",
                  "provenance_classification": "baladiyah_explicit"
