                {
                  "fact_key": "handwash-dry",
                  "presentation": "step",
                  "position": 4,
                  "text": "جفّف بمنشفة ورقية أحادية الاستخدام أو بمجفف الهواء، ثم استخدم المنشفة لإغلاق الصنبور.",
                  "provenance_classification": "baladiyah_explicit"
