              "items": [
                {
                  "fact_key": "handwash-wet",
                  "presentation": "step",
                  "position": 1,
                  "text": "Basain ang mga kamay sa maligamgam na dumadaloy na tubig na 38°C-43°C.",
                  "provenance_classification": "baladiyah_explicit"
