                  "fact_key": "handwash-soap",
                  "presentation": "step",
                  "position": 2,
                  "text": "Gumamit ng antibacterial liquid soap, hindi bar soap.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-scrub",
                  "presentation": "step",
                  "position": 3,
                  "text": "Kuskusin ang palad, likod ng kamay, pagitan ng mga daliri, ilalim ng kuko, hinlalaki, at pulsuhan nang hindi bababa sa 20 segundo.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-dry",
                  "presentation": "step",
                  "position": 4,
                  "text": "Patuyuin gamit ang single-use paper towel o air dryer, saka gamitin ang towel sa pagsara ng gripo.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "handwash-triggers",
                  "presentation": "key_point",
                  "position": 5,
                  "text": "Maghugas ng kamay bago ang shift at pagkatapos gumamit ng palikuran, humawak sa mukha o buhok, umubo o bumahing, humawak ng hilaw na pagkain o basura, o humawak ng pera o cashier device.",
                  "provenance_classification": "baladiyah_explicit"
                },
                {
                  "fact_key": "protected-cut",
                  "presentation": "warning",
                  "position": 6,
                  "text": "Lagyan ng antiseptic ang sugat, takpan ng asul na waterproof bandage, at protektahan gamit ang disposable gloves.",
                  "provenance_classification": "baladiyah_explicit"
                }
