          "content_i18n": {
            "en": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "separate-raw-rte",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "Keep raw products fully separated from cooked or ready-to-eat food.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "illness-exclusion",
                  "presentation": "warning",
                  "position": 2,
                  "text": "Apply exclusion or restriction before food work when staff have gastroenteritis symptoms.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "pathogen-sources",
                  "presentation": "key_point",
                  "position": 3,
                  "text": "The current curriculum links Salmonella to raw poultry and eggs, E. coli to raw ground beef, contaminated produce, or unfiltered water, Staphylococcus aureus to staff wounds, nose, or mouth, and Norovirus to fecal-oral transmission and poor hand hygiene.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "temperature-danger-zone",
                  "presentation": "warning",
                  "position": 4,
                  "text": "The Temperature Danger Zone is 5°C-60°C, and the current curriculum says TCS food must not remain there longer than 2 hours.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "symptom-free-return",
                  "presentation": "corrective_action",
                  "position": 5,
                  "text": "For the current vomiting and diarrhea scenario, the curriculum requires the employee to remain symptom-free for 24-48 hours before returning to food handling.",
                  "provenance_classification": "existing_training_supporting"
                }
              ]
            },
            "ar": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "separate-raw-rte",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "افصل المنتجات النيئة تماماً عن الطعام المطهو أو الجاهز للأكل.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "illness-exclusion",
                  "presentation": "warning",
                  "position": 2,
                  "text": "طبّق الاستبعاد أو التقييد قبل العمل بالطعام عندما تظهر على الموظف أعراض التهاب المعدة والأمعاء.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "pathogen-sources",
                  "presentation": "key_point",
                  "position": 3,
                  "text": "يربط المنهج الحالي السالمونيلا بالدواجن والبيض النيء، والإشريكية القولونية باللحم المفروم النيء أو الخضار الملوثة أو الماء غير المصفى، والمكورات العنقودية الذهبية بجروح العامل أو أنفه أو فمه، والنوروفيروس بالانتقال البرازي الفموي وضعف نظافة اليدين.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "temperature-danger-zone",
                  "presentation": "warning",
                  "position": 4,
                  "text": "منطقة خطر الحرارة هي 5°C-60°C، ويذكر المنهج الحالي أن طعام TCS يجب ألا يبقى فيها لأكثر من ساعتين.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "symptom-free-return",
                  "presentation": "corrective_action",
                  "position": 5,
                  "text": "في سيناريو القيء والإسهال الحالي، يشترط المنهج بقاء الموظف بلا أعراض لمدة 24-48 ساعة قبل العودة للتعامل مع الطعام.",
                  "provenance_classification": "existing_training_supporting"
                }
              ]
            },
            "id": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "separate-raw-rte",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "Pisahkan produk mentah sepenuhnya dari makanan matang atau siap santap.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "illness-exclusion",
                  "presentation": "warning",
                  "position": 2,
                  "text": "Terapkan larangan atau pembatasan sebelum bekerja dengan makanan ketika staf memiliki gejala gastroenteritis.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "pathogen-sources",
                  "presentation": "key_point",
                  "position": 3,
                  "text": "Kurikulum saat ini mengaitkan Salmonella dengan unggas dan telur mentah, E. coli dengan daging giling mentah, hasil bumi terkontaminasi, atau air tanpa filtrasi, Staphylococcus aureus dengan luka, hidung, atau mulut staf, serta Norovirus dengan penularan fekal-oral dan kebersihan tangan yang buruk.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "temperature-danger-zone",
                  "presentation": "warning",
                  "position": 4,
                  "text": "Temperature Danger Zone adalah 5°C-60°C, dan kurikulum saat ini menyatakan makanan TCS tidak boleh berada di sana lebih dari 2 jam.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "symptom-free-return",
                  "presentation": "corrective_action",
                  "position": 5,
                  "text": "Untuk skenario muntah dan diare saat ini, kurikulum mensyaratkan karyawan bebas gejala selama 24-48 jam sebelum kembali menangani makanan.",
                  "provenance_classification": "existing_training_supporting"
                }
              ]
            },
            "hi": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "separate-raw-rte",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "कच्चे उत्पादों को पके या खाने के लिए तैयार भोजन से पूरी तरह अलग रखें।",
                  "provenance_classification": "existing_training_supporting"
                },
