                  "fact_key": "separate-raw-rte",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "Ganap na ihiwalay ang raw products sa cooked o ready-to-eat food.",
                  "provenance_classification": "existing_training_supporting"
