                  "fact_key": "illness-exclusion",
                  "presentation": "warning",
                  "position": 2,
                  "text": "Magpatupad ng exclusion o restriction bago humawak ng pagkain kapag may sintomas ng gastroenteritis ang staff.",
                  "provenance_classification": "existing_training_supporting"
