                },
                {
                  "fact_key": "symptom-free-return",
                  "presentation": "corrective_action",
                  "position": 5,
                  "text": "Sa kasalukuyang senaryo ng pagsusuka at pagtatae, kailangan ng kurikulum na walang sintomas ang empleyado sa loob ng 24-48 oras bago bumalik sa food handling.",
                  "provenance_classification": "existing_training_supporting"
                }
