                },
                {
                  "fact_key": "board-colors",
                  "presentation": "key_point",
                  "position": 4,
                  "text": "Use red for raw red meat, yellow for poultry, blue for seafood, green for produce, brown for cooked meat, and white for ready-to-eat food, dairy, or bread.",
