            "hi": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "biological-hazards",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "जैविक खतरों में बैक्टीरिया, वायरस, फफूँद, परजीवी और बीजाणु शामिल हैं; वर्तमान पाठ्यक्रम कच्ची पोल्ट्री से Salmonella को उदाहरण बनाता है।",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "chemical-hazards",
                  "presentation": "key_point",
                  "position": 2,
                  "text": "रासायनिक खतरों में कीटनाशक अवशेष, सफाई रसायन, जंग और गलत तरीके से रखे रसायन शामिल हैं।",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "physical-hazards",
                  "presentation": "key_point",
                  "position": 3,
                  "text": "भौतिक खतरों में बाल, काँच, स्टेपल, कील और आभूषण शामिल हैं।",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "board-colors",
                  "presentation": "key_point",
                  "position": 4,
                  "text": "कच्चे लाल मांस के लिए लाल, पोल्ट्री के लिए पीला, समुद्री भोजन के लिए नीला, फल-सब्ज़ी के लिए हरा, पके मांस के लिए भूरा और खाने के लिए तैयार भोजन, डेयरी या ब्रेड के लिए सफेद उपयोग करें।",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "major-allergens",
                  "presentation": "key_point",
                  "position": 5,
                  "text": "वर्तमान पाठ्यक्रम दूध, अंडा, मूँगफली या ट्री नट्स, ग्लूटेन, सोया, मछली, क्रस्टेशियन और तिल को प्रमुख एलर्जेन बताता है।",
                  "provenance_classification": "existing_training_supporting"
                }
              ],
              "image_slots": [
                {
                  "asset_key": "contamination-raw-rte-separation",
                  "placement": "comparison-card",
                  "slot_position": 1,
                  "label": "कच्ची पोल्ट्री खाने के लिए तैयार भोजन के नीचे और अलग रखी हुई।"
                },
                {
                  "asset_key": "contamination-board-colors",
                  "placement": "reference-card",
                  "slot_position": 2,
                  "label": "सूचीबद्ध भोजन समूहों के लिए व्यवस्थित छह रंग-कोडित कटिंग बोर्ड।"
                },
                {
                  "asset_key": "contamination-hazard-examples",
                  "placement": "hazard-cards",
                  "slot_position": 3,
                  "label": "संदूषण खतरों के रूप में कच्ची पोल्ट्री, भोजन के पास सफाई रसायन और स्टेपल के अलग उदाहरण।"
                }
              ]
            },
            "fil": {
              "content_schema_version": 1,
              "layout": "photo_first",
              "mode": "reference",
              "items": [
                {
                  "fact_key": "biological-hazards",
                  "presentation": "key_point",
                  "position": 1,
                  "text": "Kabilang sa biological hazards ang bacteria, virus, fungi, parasite, at spores; ginagamit ng kasalukuyang kurikulum ang Salmonella mula sa raw poultry bilang halimbawa.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "chemical-hazards",
                  "presentation": "key_point",
                  "position": 2,
                  "text": "Kabilang sa chemical hazards ang pesticide residue, cleaning chemicals, kalawang, at maling nakaimbak na kemikal.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "physical-hazards",
                  "presentation": "key_point",
                  "position": 3,
                  "text": "Kabilang sa physical hazards ang buhok, salamin, staple, pako, at alahas.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "board-colors",
                  "presentation": "key_point",
                  "position": 4,
                  "text": "Gamitin ang pula sa raw red meat, dilaw sa poultry, asul sa seafood, berde sa produce, kayumanggi sa cooked meat, at puti sa ready-to-eat food, dairy, o bread.",
                  "provenance_classification": "existing_training_supporting"
                },
                {
                  "fact_key": "major-allergens",
                  "presentation": "key_point",
                  "position": 5,
                  "text": "Nakalista sa kasalukuyang kurikulum ang gatas, itlog, peanut o tree nuts, gluten, soy, isda, crustaceans, at sesame bilang major allergens.",
                  "provenance_classification": "existing_training_supporting"
                }
