                {
                  "fact_key": "receiving-transfer-time",
                  "presentation": "step",
                  "position": 4,
                  "text": "انقل الطعام سريع التلف المقبول إلى المبرد أو المجمد خلال 15 دقيقة.",
                  "provenance_classification": "existing_training_supporting"
                }
              ],
              "image_slots": [
