$manifest$::jsonb;
  expected_source_hash constant text := '5d77e1c5d9c127a7a07fb0caf0703b52a0df2b16e0510632ff57bf4c09cf1515';
  expected_target_hash constant text := '9bfb8467b8a43dc61db87833d0532403d14ecc6d3f63cb57e37582ea32d634d3';
  target_organization_id uuid;
  target_course_id uuid;
  target_course_version_id uuid;
  current_status text;
  current_revision bigint;
  current_content_hash text;
  course_count integer;
  version_count integer;
  deleted_quiz_count integer;
  final_module jsonb;
  final_lesson jsonb;
  final_module_id uuid;
  slots_before jsonb;
  slots_after jsonb;
  media_before jsonb;
  media_after jsonb;
begin
  select count(*)::integer
  into course_count
  from public.training_courses course
  where course.course_key = 'baladiyah-food-safety-hygiene';

  if course_count <> 1 then
    raise exception 'Baladiyah final assessment requires exactly one course; found %', course_count
      using errcode = '55000';
  end if;

  select course.organization_id, course.id
  into target_organization_id, target_course_id
  from public.training_courses course
  where course.course_key = 'baladiyah-food-safety-hygiene';

  select count(*)::integer
  into version_count
  from public.training_course_versions version
  where version.organization_id = target_organization_id
    and version.course_id = target_course_id
    and version.version_number = 1;

  if version_count <> 1 then
    raise exception 'Baladiyah final assessment requires exactly one Version 1; found %', version_count
      using errcode = '55000';
  end if;

  select version.id, version.status, version.revision, version.content_hash
  into target_course_version_id, current_status, current_revision, current_content_hash
  from public.training_course_versions version
  where version.organization_id = target_organization_id
    and version.course_id = target_course_id
    and version.version_number = 1
  for update;

  if current_status <> 'draft' then
    raise exception 'Baladiyah Version 1 must remain draft for final assessment restructuring'
      using errcode = '55000';
  end if;

  if current_revision = 2 and current_content_hash = expected_target_hash then
    if private.baladiyah_final_assessment_target_matches(
      target_organization_id,
      target_course_id,
      target_course_version_id,
      expected_target_manifest,
      expected_target_hash,
      expected_slots
    ) then
      return;
    end if;
    raise exception 'Baladiyah final assessment target has drifted' using errcode = '55000';
  end if;

  if current_revision <> 1 or current_content_hash is distinct from expected_source_hash
    or not private.baladiyah_final_assessment_source_matches(
      target_organization_id,
      target_course_id,
      target_course_version_id,
      expected_target_manifest,
      expected_source_quizzes,
      expected_slots
    ) then
    raise exception 'Baladiyah final assessment source precondition failed' using errcode = '55000';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'module_key', slot.module_key,
        'lesson_key', slot.lesson_key,
        'asset_key', slot.asset_key,
        'placement', slot.placement,
        'slot_position', slot.slot_position
      ) order by slot.module_position, slot.lesson_position, slot.slot_position
    ),
    '[]'::jsonb
  )
  into slots_before
  from private.training_image_slot_requirements(target_organization_id, target_course_version_id) slot;

  select coalesce(jsonb_agg(to_jsonb(asset) order by asset.id), '[]'::jsonb)
  into media_before
  from public.training_media_assets asset
  where asset.organization_id = target_organization_id
    and asset.course_version_id = target_course_version_id;

  delete from public.training_lessons lesson
  using public.training_modules module
  where lesson.module_id = module.id
    and lesson.organization_id = target_organization_id
    and lesson.course_version_id = target_course_version_id
    and module.organization_id = target_organization_id
    and module.course_version_id = target_course_version_id
    and module.position between 1 and 9
    and lesson.stable_key = 'knowledge-check'
    and lesson.lesson_type = 'quiz';
  get diagnostics deleted_quiz_count = row_count;

  if deleted_quiz_count <> 9 then
    raise exception 'Baladiyah final assessment expected to remove 9 source quizzes; removed %', deleted_quiz_count
      using errcode = '55000';
  end if;

  final_module := expected_target_manifest #> '{modules,9}';
  final_lesson := final_module #> '{lessons,0}';

  insert into public.training_modules(
    organization_id,
    course_version_id,
    stable_key,
    position,
    category_key,
    title_i18n,
    description_i18n,
    metadata
  ) values (
    target_organization_id,
    target_course_version_id,
    final_module ->> 'stable_key',
    (final_module ->> 'position')::integer,
    final_module ->> 'category_key',
    final_module -> 'title_i18n',
    final_module -> 'description_i18n',
    final_module -> 'metadata'
  )
  returning id into final_module_id;

  insert into public.training_lessons(
    organization_id,
    course_version_id,
    module_id,
    stable_key,
    position,
    lesson_type,
    required,
    title_i18n,
    objective_i18n,
    content_i18n,
    estimated_duration_seconds,
    minimum_engagement_seconds,
    pass_threshold_bps,
    max_attempts,
    retry_delay_seconds,
    metadata
  ) values (
    target_organization_id,
    target_course_version_id,
    final_module_id,
    final_lesson ->> 'stable_key',
    (final_lesson ->> 'position')::integer,
    final_lesson ->> 'lesson_type',
    (final_lesson ->> 'required')::boolean,
    final_lesson -> 'title_i18n',
    final_lesson -> 'objective_i18n',
    final_lesson -> 'content_i18n',
    (final_lesson ->> 'estimated_duration_seconds')::integer,
    (final_lesson ->> 'minimum_engagement_seconds')::integer,
    (final_lesson ->> 'pass_threshold_bps')::integer,
    (final_lesson ->> 'max_attempts')::integer,
    (final_lesson ->> 'retry_delay_seconds')::integer,
    final_lesson -> 'metadata'
  );

  update public.training_course_versions version
  set revision = 2,
      content_hash = expected_target_hash
  where version.id = target_course_version_id
    and version.organization_id = target_organization_id
    and version.course_id = target_course_id
    and version.status = 'draft';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'module_key', slot.module_key,
        'lesson_key', slot.lesson_key,
        'asset_key', slot.asset_key,
        'placement', slot.placement,
        'slot_position', slot.slot_position
      ) order by slot.module_position, slot.lesson_position, slot.slot_position
    ),
    '[]'::jsonb
  )
  into slots_after
  from private.training_image_slot_requirements(target_organization_id, target_course_version_id) slot;

  select coalesce(jsonb_agg(to_jsonb(asset) order by asset.id), '[]'::jsonb)
  into media_after
  from public.training_media_assets asset
  where asset.organization_id = target_organization_id
    and asset.course_version_id = target_course_version_id;

  if slots_after is distinct from slots_before or slots_after is distinct from expected_slots then
    raise exception 'Baladiyah final assessment changed the required image-slot contract'
      using errcode = '55000';
  end if;

  if media_after is distinct from media_before then
    raise exception 'Baladiyah final assessment changed Training media rows'
      using errcode = '55000';
  end if;

  if not private.baladiyah_final_assessment_target_matches(
    target_organization_id,
    target_course_id,
    target_course_version_id,
    expected_target_manifest,
    expected_target_hash,
    expected_slots
  ) then
    raise exception 'Baladiyah final assessment target validation failed' using errcode = '55000';
  end if;
end;
$function$;

select private.restructure_baladiyah_final_assessment();

revoke all on function private.baladiyah_final_assessment_slots_match(uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;
revoke all on function private.baladiyah_final_assessment_source_matches(uuid,uuid,uuid,jsonb,jsonb,jsonb)
  from public, anon, authenticated, service_role;
revoke all on function private.baladiyah_final_assessment_target_matches(uuid,uuid,uuid,jsonb,text,jsonb)
  from public, anon, authenticated, service_role;
revoke all on function private.restructure_baladiyah_final_assessment()
  from public, anon, authenticated, service_role;

comment on function private.restructure_baladiyah_final_assessment() is
  'Owner-only, fail-closed migration helper for the draft Baladiyah course-level final assessment.';
